// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.brain.orchestratorimport com.roshan.persona.brain.context.BrainContextimport com.roshan.persona.brain.context.SessionIdimport com.roshan.persona.brain.trace.BrainTraceimport com.roshan.persona.common.CorrelationIdimport java.time.Instant/** * NOUS — Brain response (final output of a brain request). * * Produced by [BrainOrchestrator.process] after routing through all 6 layers, * post-processing, and audit logging. Contains: * *   - **message**: the text response shown in chat UI *   - **spokenMessage**: TTS-optimized version (emoji stripped, simplified) *   - **trace**: full [BrainTrace] audit log (layer-by-layer decisions) *   - **suggestions**: actionable follow-up suggestions for the user *   - **metadata**: cost, tokens, latency, which layer handled it *   - **status**: SUCCESS / PARTIAL / FAILURE / NEEDS_PERMISSION / NEEDS_INPUT * * ## Streaming * * For LLM responses (Layer 3/4), tokens stream to UI in real-time via * [StreamCoordinator]. The [message] field is the FULL final text (assembled * after streaming completes). UI can choose to show streamed tokens live OR * wait for the final [BrainResponse]. * * ## Privacy * *   - [message] may contain user data (it's the LLM's response to user input) *   - [trace] contains PII-scrubbed input (never raw) *   - Both are stored on-device only, never synced to cloud *   - User can view + delete in Settings → Privacy → Conversation History * * @see <a href="docs/spec/module2-spec-review.pdf">§10 Brain Response</a> */data class BrainResponse(    /** Correlation ID — joins all layers of this request. */    val correlationId: CorrelationId,    /** Session ID — links to conversation. */    val sessionId: SessionId,    /** When the request was received by the brain. */    val receivedAt: Instant,    /** When the response was finalized. */    val completedAt: Instant,    /** Total wall-clock duration in milliseconds. */    val totalDurationMs: Long,    /** Text response shown in chat UI. */    val message: String,    /** TTS-optimized version (emoji stripped, simplified). Null = same as [message]. */    val spokenMessage: String?,    /** Full audit log of layer decisions. */    val trace: BrainTrace,    /** Which layer produced the final response. */    val handledBy: BrainLayer,    /** Final status (success / partial / failure / needs-input / needs-permission). */    val status: BrainResponseStatus,    /** Total USD cost of this request (0 for rule/skill, >0 for cloud LLM). */    val costUsd: Float,    /** Total LLM tokens generated (0 for rule/skill). */    val tokensGenerated: Int,    /** Actionable suggestions for the user (e.g., "Enable cloud in Settings"). */    val suggestions: List<BrainSuggestion> = emptyList(),    /** Whether the response was streamed token-by-token to UI. */    val wasStreamed: Boolean = false,    /** Optional warning messages (e.g., "low confidence", "fell back to cloud"). */    val warnings: List<String> = emptyList(),) {    /** Whether the request succeeded. */    val isSuccess: Boolean get() = status == BrainResponseStatus.SUCCESS    /** Whether the request was partial (completed with warnings). */    val isPartial: Boolean get() = status == BrainResponseStatus.PARTIAL    /** Whether the request failed. */    val isFailure: Boolean get() = status == BrainResponseStatus.FAILURE    /** Whether the request needs user input to continue. */    val needsInput: Boolean get() = status == BrainResponseStatus.NEEDS_INPUT    /** Whether the request needs a permission to continue. */    val needsPermission: Boolean get() = status == BrainResponseStatus.NEEDS_PERMISSION}/** * Which brain layer produced the final response. */enum class BrainLayer(val number: Int, val displayName: String) {    /** Layer 0 — IntentClassifier (rarely produces final response, only for Unknown intents). */    INTENT(0, "IntentClassifier"),    /** Layer 1 — RuleEngine (instant rule fire, e.g., "torch on"). */    RULE(1, "RuleEngine"),    /** Layer 2 — SkillRouter (skill execution, e.g., "call mom"). */    SKILL(2, "SkillRouter"),    /** Layer 3 — LocalLLM (on-device LLM inference). */    LOCAL_LLM(3, "LocalLLM"),    /** Layer 4 — CloudLLM (cloud LLM inference, user opt-in). */    CLOUD_LLM(4, "CloudLLM"),    /** Layer 5 — AgenticOrchestrator (multi-step ReAct workflow). */    AGENTIC(5, "AgenticOrchestrator"),    /** No layer handled it (all failed or user-interrupted). */    NONE(-1, "None");    companion object {        fun fromNumber(number: Int): BrainLayer? = entries.firstOrNull { it.number == number }    }}/** * Final status of a brain request. */enum class BrainResponseStatus {    /** Request completed successfully. */    SUCCESS,    /** Request completed with warnings (e.g., low confidence, fell back). */    PARTIAL,    /** Request failed (all layers failed or guardrail hit). */    FAILURE,    /** Request paused — skill needs user input to resume. */    NEEDS_INPUT,    /** Request paused — skill needs permission to execute. */    NEEDS_PERMISSION,    /** Request cancelled by user (barge-in / explicit cancel). */    CANCELLED,}/** * Actionable suggestion shown to the user (e.g., in chat UI below the response). * * Used when the brain can't fully satisfy the request but knows what the user * should do next (e.g., "Download a model", "Enable cloud", "Grant permission"). */data class BrainSuggestion(    /** Human-readable suggestion text. */    val text: String,    /** Type of action (drives UI icon + behavior). */    val type: SuggestionType,    /** Optional deep link (e.g., "nous://settings/ai-models"). */    val deepLink: String? = null,    /** Optional action label (e.g., "Download", "Enable", "Grant"). */    val actionLabel: String? = null,)/** * Type of suggestion — drives UI presentation. */enum class SuggestionType {    /** Download a local LLM model. */    DOWNLOAD_MODEL,    /** Enable a cloud provider. */    ENABLE_CLOUD,    /** Grant a permission. */    GRANT_PERMISSION,    /** Open settings. */    OPEN_SETTINGS,    /** Rephrase the request. */    REPHRASE,    /** Try a different approach. */    TRY_DIFFERENT,    /** General info (no action). */    INFO,}